WHO = {'column': [('aprilylglo', 319164), ('eincyclsof', 319164), ('rofyoocgepy', 0), ('rofyomumae', 0), ('unelwei', 0), ('qum', 319548), ('uneloicro', 319548), ('kidcfools', 319548)], 'manor': [('mugeldmicro', 319420), ('uneloumae', 319740), ('orgdmolglo', 0), ('uneloumae', 0), ('mugeldmicro', 330843)], 'tree': [('elgepy', 319612), ('aprilylglo', 319612), ('aprilcero', 0), ('elgepy', 0), ('aprilylglo', 0), ('aprillgepy', 325575), ('aprilylglo', 330081), ('aprillgepy', 0)], 'bridge': [('qudmicro', 319740), ('kavcydmicro', 320816), ('orgdmdmicro', 320816), ('kavcydmicro', 321072), ('alphafoldmicro', 322148), ('orgdmfools', 322910), ('orgdmdmicro', 323160), ('kidcgepy', 324178)], 'tower': [('dunolsof', 320560), ('rofyoocgepy', 323160), ('kavcydcgepy', 323416), ('rofyomumae', 0), ('orgdmdmicro', 330081), ('kidcgepy', 331286), ('dunolsof', 331862), ('rofyoocgepy', 0)], 'temple': [('aprilfools', 321008), ('mumcoocgepy', 322718), ('alphafoldmicro', 328435), ('mumcoocgepy', 331035), ('aprilfools', 0)], 'castle': [('bridgepy', 327481)]}

EPI_RX = re.compile(
    r"^(?:what (?:has|have) (?P<a>[\w'\- ]{2,24}?) (?:done|been doing)"
    r"|what happened (?:with|to) (?P<b>[\w'\- ]{2,24}?))[?.! ]*$", re.I)
WHO_RX = re.compile(
    r"^who (?:built|made|raised) (?:a |an |the )?(?P<k>[\w \-]{2,24}?)[?.! ]*$", re.I)


class OracleReleaseRuntimeW105(OracleReleaseRuntimeW103):
    """Base + episodic recall. Fires only on bound episodes; else the chain answers."""

    def chat(self, text: str, session_id: str = "default") -> dict:
        s = " ".join(str(text).strip().split())
        m = EPI_RX.match(s)
        if m:
            actor = (m.group("a") or m.group("b") or "").strip().lower()
            eps = EPI.get(actor)
            if eps:
                bits = "; ".join(f"at tick {t} {v} {o}" for t, v, o in eps[-5:])
                pending = getattr(self, "_pending_conversion", None)
                if pending is None:
                    pending = self._pending_conversion = {}
                pending[session_id] = {"construction": "EPISODIC_RECALL",
                                        "from": s[:80], "to": f"episodes({actor})",
                                        "produced_by": "oracle_fold_worker_v4"}
                return {"status": "answered", "path": "worker:episodic",
                         "response": f"The record holds for {actor}: {bits}. "
                                     f"[world_ledger_ew2]",
                         "provenance": {"kind": "episodic_ledger", "actor": actor,
                                         "episodes": len(eps)},
                         "latency_ms": 1}
        w = WHO_RX.match(s)
        if w:
            kind = w.group("k").strip().lower()
            hits = WHO.get(kind) or WHO.get(kind.rstrip("s"))
            if hits:
                bits = ", ".join(f"{a} (tick {t})" for a, t in hits[-4:])
                return {"status": "answered", "path": "worker:episodic_who",
                         "response": f"By the world record, {kind}s were raised by "
                                     f"{bits}. [world_ledger_ew2]",
                         "provenance": {"kind": "episodic_ledger", "object": kind},
                         "latency_ms": 1}
        return super().chat(s, session_id)
